"""Recompute published scalar metrics from every raw clip, independently of plot/report code."""
import datetime,json,math,statistics
from pathlib import Path
r=Path(__file__).parent;repo=Path('/home/ubuntu/workspace/chase/EmbodiedForge');run=repo/'runs/supermimic-reproduction-20261027-fourhour';comparison=json.loads((r/'comparison.json').read_text());verified={};clip_ids=None
for label,record in comparison['evaluations'].items():
 rows=json.loads((run/label/'evaluation.json').read_text())['clips'];assert len(rows)==40
 ids={x['name'] for x in rows};assert len(ids)==40
 if clip_ids is None:clip_ids=ids
 assert ids==clip_ids
 steps=sum(x['steps'] for x in rows);frames=sum(x['frames'] for x in rows);reward=sum(x['norm_return']*x['steps'] for x in rows)
 expected={'clips':40,'failed':sum(x['failed'] for x in rows),'mean_norm_return':statistics.mean(x['norm_return'] for x in rows),'step_weighted_norm_return':reward/steps,'full_clip_zero_padded_return':reward/frames,'raw_steps_to_nominal_frames':steps/frames,'completed_frames_fraction':sum(min(x['steps'],x['frames']) for x in rows)/frames}
 actual=record['result']['summary']
 for key,value in expected.items():assert math.isclose(actual[key],value,rel_tol=1e-12,abs_tol=1e-12),(label,key,actual[key],value)
 verified[label]=expected
for kind,conditions in comparison['aggregate'].items():
 for condition,group in conditions.items():
  values=[value for label,value in verified.items() if label.startswith(kind+'-'+condition+'-')];assert len(values)==group['repeats']==3
  for metric,stats in group['metrics'].items():
   nums=[x[metric] for x in values];expected={'mean':statistics.mean(nums),'min':min(nums),'max':max(nums),'median':statistics.median(nums)}
   for name,value in expected.items():assert math.isclose(stats[name],value,rel_tol=1e-12,abs_tol=1e-12),(kind,condition,metric,name)
for condition in ('paper-resume','anchor-resume','anchor-recovery-smoke'):
 result=json.loads((run/condition/'result.json').read_text());assert result['final_updates']-result['initial_updates']==result['new_updates'];assert result['final_iteration']-result['initial_iteration']==result['new_environment_steps']
proof={'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'all_checks_passed':True,'evaluations_recomputed':len(verified),'raw_clip_records_recomputed':sum(v['clips'] for v in verified.values()),'consistent_clip_ids':sorted(clip_ids),'metric_tolerance':1e-12,'training_update_deltas_verified':True,'scope':'Arithmetic and record consistency checks only. Original anchor training remains quarantined exit1; this does not validate training data continuity.'};(r/'metric-integrity.json').write_text(json.dumps(proof,indent=2)+'\n');print(json.dumps({k:v for k,v in proof.items() if k!='consistent_clip_ids'}))

